import React, { useState, useCallback, useEffect } from "react";
import { useDropzone } from "react-dropzone";
import ExifReader from "exifreader";
import SparkMD5 from "spark-md5";
import CryptoJS from "crypto-js";
import { useTheme } from "../component/ThemeContext";

export default function ImageForensics() {
  const { theme } = useTheme();
  const isDark = theme === "dark";

  const [fileData, setFileData] = useState(null);
  const [preview, setPreview] = useState(null);
  const [loading, setLoading] = useState(false);

  // ================= HASH =================
  const generateHashes = async (file) => {
    const buffer = await file.arrayBuffer();
    const md5 = SparkMD5.ArrayBuffer.hash(buffer);
    const wordArray = CryptoJS.lib.WordArray.create(buffer);

    return {
      md5,
      sha1: CryptoJS.SHA1(wordArray).toString(),
      sha256: CryptoJS.SHA256(wordArray).toString(),
    };
  };

  // ================= EXIF =================
  const extractExif = async (file) => {
    try {
      const tags = await ExifReader.load(await file.arrayBuffer());
      return {
        camera: tags.Model?.description,
        brand: tags.Make?.description,
        lens: tags.LensModel?.description,
        date: tags.DateTimeOriginal?.description,
        gps: tags.GPSLatitude
          ? `${tags.GPSLatitude.description}, ${tags.GPSLongitude.description}`
          : null,
        software: tags.Software?.description,
      };
    } catch {
      return {};
    }
  };

  // ================= AI =================
  const detectAI = async (file) => {
    const text = await file.text();

    let score = 0;
    let signals = [];

    const rules = [
      ["Midjourney", 40],
      ["Stable Diffusion", 40],
      ["OpenAI", 40],
      ["DALL-E", 40],
      ["Adobe", 20],
    ];

    rules.forEach(([k, v]) => {
      if (text.includes(k)) {
        score += v;
        signals.push(k);
      }
    });

    return {
      score,
      isAI: score >= 40,
      isEdited: score >= 20,
      signals,
    };
  };

  // ================= PROCESS =================
  const processFile = async (file) => {
    setLoading(true);

    const url = URL.createObjectURL(file);
    setPreview(url);

    const hashes = await generateHashes(file);
    const exif = await extractExif(file);
    const ai = await detectAI(file);

    const img = new Image();
    img.onload = () => {
      setFileData({
        name: file.name,
        size: (file.size / 1024).toFixed(2) + " KB",
        type: file.type,
        lastModified: new Date(file.lastModified).toLocaleString(),
        resolution: `${img.width} × ${img.height}`,
        hashes,
        exif,
        ai,
      });
      setLoading(false);
    };
    img.src = url;
  };

  // ================= DROP =================
  const onDrop = useCallback((files) => processFile(files[0]), []);
  const { getRootProps, getInputProps } = useDropzone({
    accept: { "image/*": [] },
    onDrop,
  });

  // ================= CLIPBOARD =================
  useEffect(() => {
    const paste = (e) => {
      const item = [...e.clipboardData.items].find((i) =>
        i.type.includes("image")
      );
      if (item) processFile(item.getAsFile());
    };
    window.addEventListener("paste", paste);
    return () => window.removeEventListener("paste", paste);
  }, []);

  // ================= COPY =================
  const copy = (txt) => navigator.clipboard.writeText(txt);

  // ================= STYLES =================
  const bg = isDark ? "#0f172a" : "#f8fafc";
  const card = isDark ? "#1e293b" : "#ffffff";
  const text = isDark ? "#e2e8f0" : "#0f172a";

  return (
    <div style={{ background: bg, color: text, minHeight: "100vh", padding: 20 }}>
      
      {/* UPLOAD */}
      <div
        {...getRootProps()}
        style={{
          border: "2px dashed #64748b",
          borderRadius: 12,
          padding: 20,
          textAlign: "center",
          marginBottom: 20,
          cursor: "pointer",
        }}
      >
        <input {...getInputProps()} />
        <b>Upload / Drag / Paste Image</b>
      </div>

      {loading && <p>Analyzing...</p>}

      {fileData && (
        <>
          <div className="row g-4">

            {/* LEFT IMAGE */}
            <div className="col-md-4">
              <div style={{ background: card, padding: 10, borderRadius: 12 }}>
                <img src={preview} className="img-fluid rounded" />
              </div>
            </div>

            {/* RIGHT DETAILS */}
            <div className="col-md-8 d-flex flex-column gap-3">

              {/* STATUS */}
              <div style={{ background: card, padding: 15, borderRadius: 12 }}>
                <b>Status</b>
                <p>AI Generated: {fileData.ai.isAI ? "YES" : "NO"}</p>
                <p>Edited: {fileData.ai.isEdited ? "YES" : "NO"}</p>
                <p>Signals: {fileData.ai.signals.join(", ") || "None"}</p>
              </div>

              {/* FILE */}
              <div style={{ background: card, padding: 15, borderRadius: 12 }}>
                <b>File Info</b>
                <p>{fileData.name}</p>
                <p>{fileData.size}</p>
                <p>{fileData.type}</p>
                <p>{fileData.resolution}</p>
                <p>{fileData.lastModified}</p>
              </div>

              {/* EXIF */}
              <div style={{ background: card, padding: 15, borderRadius: 12 }}>
                <b>Metadata</b>
                <p>Camera: {fileData.exif.camera}</p>
                <p>Brand: {fileData.exif.brand}</p>
                <p>Lens: {fileData.exif.lens}</p>
                <p>GPS: {fileData.exif.gps || "N/A"}</p>
                <p>Software: {fileData.exif.software}</p>
              </div>

            </div>
          </div>

          {/* BOTTOM HASH BLOCK */}
          <div
            style={{
              background: "#020617",
              color: "#22c55e",
              marginTop: 20,
              padding: 15,
              borderRadius: 12,
              fontFamily: "monospace",
              fontSize: 13,
            }}
          >
            <div className="d-flex justify-content-between">
              <b>Hashes</b>
              <button onClick={() => copy(JSON.stringify(fileData.hashes))}>
                Copy
              </button>
            </div>

            <p>MD5: {fileData.hashes.md5}</p>
            <p>SHA1: {fileData.hashes.sha1}</p>
            <p>SHA256: {fileData.hashes.sha256}</p>
          </div>
        </>
      )}
    </div>
  );
}